// === Tab: mySketch ===
let numSegs = 40;
let horiz;


function setup() {
  createCanvas(550, 600);
  // noLoop() removed for animation
}

function draw() {
  background(255);
	stroke(0, 150);
  strokeWeight(2);
	noFill();
  rect(0, 0, width-1, height-1);
  drawPaper();
  subDivide(5, 50, 50, width-100, height-100);
}


function subDivide(n, x, y, w, h) {
  if (n==0) {
    noFill();
    drawRect(x, y, w, h);
    let linesHoriz =  random(1) > 0.5 ? true : false;
    let limitW = random(w);
    let limitH = random(h);
    if (linesHoriz) {
      for (let j = y; j < (h+y); j+=5) {
        drawLine(x, j, x + limitW, j, false);
      }
    } else {
      for (let i = x; i < (w+x); i+=5) {
        drawLine(i, y, i, y + limitH, false);
      }
    }
  } else {
    let t = random(1);
    var horiz =  random(1) > 0.5 ? true : false;
    if (horiz) {
      subDivide(n-1, x, y, w, h*t);
      subDivide(n-1, x, y+h*t, w, h*(1-t));
    } else {
      subDivide(n-1, x, y, w*t, h);
      subDivide(n-1, x+w*t, y, w*(1-t), h);
    }
  }
}

function drawLine(strtx, strty, finx, finy, isShape) { 
  let fraction = 0;
  let divBy = numSegs;
  let x1 = strtx;
  let y1 = strty;
  for (let j = 0; j <= int (numSegs); j++) {
    let x = (randomGaussian()*.3)+x1 + (fraction * (finx-x1));
    let y = (randomGaussian()*.3)+y1 + (fraction * (finy-y1));
    if (isShape) { 
      strokeWeight(1.5); // leave separate for tweaking purposes
      stroke(80);
      vertex(x, y);
    } else {
      strokeWeight(1.5);
      stroke(80);
      line(x1, y1, x, y);
    }
    x1 = x;
    y1 = y;
    fraction = 1.0/divBy--;
  }
}


function drawRect(x, y, w, h) {
  beginShape();
  drawLine(x, y, x+w, y, true);
  drawLine(x+w, y, x+w, y+h, true);
  drawLine( x+w, y+h, x, y+h, true);
  drawLine( x, y+h, x, y, true);
  endShape();
}


function drawPaper() {
  noStroke();
  for (let i = 0; i < width; i += 2) {
    for (let j = 0; j < height; j += 2) {
      fill(random(210, 235), 150);
      rect(i, j, 2, 2);
    }
  }
  for (let i = 0; i < 50; i++) {
    fill(random(70, 110), 140);
    ellipse(random(0, width), random(0, height), random(1, 3), random(1, 3));
  }
}

function mousePressed() {
  redraw();
}
